            function refreshVoices() {
                availableVoices = window.speechSynthesis?.getVoices?.() || [];
            }

            function speakText(text, voiceName, voiceLanguage) {
                if (!voiceSettings.enabled || !('speechSynthesis' in window) || !text) return;
                refreshVoices();
                const utterance = new SpeechSynthesisUtterance(text);
                const voice = availableVoices.find(v => v.name === (voiceName || voiceSettings.voiceName))
                    || availableVoices.find(v => v.lang === (voiceLanguage || voiceSettings.voiceLanguage));
                if (voice) utterance.voice = voice;
                utterance.lang = voice?.lang || voiceLanguage || voiceSettings.voiceLanguage || 'en-US';
                utterance.rate = Number(voiceSettings.rate || 1);
                utterance.pitch = Number(voiceSettings.pitch || 1);
                utterance.volume = Number(voiceSettings.volume || 1);
                window.speechSynthesis.cancel();
                window.speechSynthesis.speak(utterance);
            }

            function speakDialogue(lines = []) {
                if (!voiceSettings.enabled || !('speechSynthesis' in window)) return;
                window.speechSynthesis.cancel();
                refreshVoices();
                lines.forEach((line) => {
                    const utterance = new SpeechSynthesisUtterance((line.speaker ? line.speaker + ': ' : '') + line.text);
                    const voice = availableVoices.find(v => v.name === line.voiceName) || availableVoices.find(v => v.lang === (line.voiceLanguage || voiceSettings.voiceLanguage));
                    if (voice) utterance.voice = voice;
                    utterance.lang = voice?.lang || line.voiceLanguage || voiceSettings.voiceLanguage || 'en-US';
                    utterance.rate = Number(voiceSettings.rate || 1);
                    utterance.pitch = Number(voiceSettings.pitch || 1);
                    utterance.volume = Number(voiceSettings.volume || 1);
                    window.speechSynthesis.speak(utterance);
                });
            }

