            // INITIALISE CAMERA PERMISSION REQUEST
            function initCamera() {
                if (!schema.proctoring?.webcamRequired) {
                    camStatusText.innerText = "📷 Simulated Tracker Mode Active";
                    return;
                }
                
                navigator.mediaDevices.getUserMedia({ video: { width: 320, height: 240 }, audio: false })
                    .then(stream => {
                        cameraStream = stream;
                        videoElem.srcObject = stream;
                        camStatusText.innerText = "📷 Face Tracking Calibrated";
                        if ('FaceDetector' in window) {
                            try { faceDetector = new window.FaceDetector({ fastMode: true, maxDetectedFaces: 1 }); } catch(e) { faceDetector = null; }
                        }
                        // Start lightweight heuristic evaluation
                        setInterval(trackFacePresenceHeuristic, Math.max(1000, (schema.proctoring?.webcamCheckFrequencySeconds || 3) * 1000));
                    })
                    .catch(err => {
                        console.warn("Webcam blocked or missing:", err);
                        camStatusText.innerText = "⚠️ Camera Blocked (Fallback Tracking)";
                        camStatusText.style.color = "var(--warning)";
                        logEvent("CAMERA_ERROR", "User denied or lacked hardware interface", false);
                    });
            }

            // SIMPLIFIED CANVAS-DIFF HEURISTIC FOR FACE/MOTION TRACKING
            // Checks pixel movement or ambient brightness to simulate robust tracking fallback
            async function trackFacePresenceHeuristic() {
                if (examSubmitted || !examStarted || !cameraStream || isPracticeMode) return;

                let subjectMissing = false;
                let nativeFaceCheckResolved = false;
                if (videoElem.paused || videoElem.ended || videoElem.readyState < 2) subjectMissing = true;

                if (!subjectMissing && faceDetector) {
                    try {
                        const faces = await faceDetector.detect(videoElem);
                        nativeFaceCheckResolved = true;
                        subjectMissing = !faces || faces.length === 0;
                    } catch(e) {}
                }

                if (!subjectMissing && !nativeFaceCheckResolved) {
                    try {
                        const canvas = document.createElement('canvas');
                        canvas.width = 96;
                        canvas.height = 72;
                        const ctx = canvas.getContext('2d', { willReadFrequently: true });
                        ctx.drawImage(videoElem, 0, 0, canvas.width, canvas.height);
                        const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
                        let brightness = 0;
                        let signature = 0;
                        for (let i = 0; i < data.length; i += 16) {
                            const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
                            brightness += avg;
                            signature += Math.abs(avg - 127);
                        }
                        brightness = brightness / (data.length / 16);
                        const diff = lastFrameSignature === null ? 999 : Math.abs(signature - lastFrameSignature);
                        lastFrameSignature = signature;
                        subjectMissing = brightness < 18 || diff < 2;
                    } catch(e) {}
                }

                if (subjectMissing) {
                    missingFaceFrames++;
                } else {
                    missingFaceFrames = 0;
                    faceBoundingBox.classList.remove('missing');
                    camStatusText.innerText = "📷 Face / presence detected";
                    camStatusText.style.color = "var(--success)";
                }

                if (missingFaceFrames >= 3) {
                    faceBoundingBox.classList.add('missing');
                    camStatusText.innerText = "⚠️ Face or active presence not detected";
                    camStatusText.style.color = "var(--danger)";
                    missingFaceFrames = 0;
                    logEvent("VIDEO_LOST", "Camera coverage dropped or subject repositioned off frame", true);
                }
            }

